1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type Result = { premium: number } | { payout: number; remainingCap: number };
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
28	const CURSE_SURCHARGE_RATE = 0.5;
29	const HIGH_ENCHANTMENT_THRESHOLD = 5;
30	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
31	const LOYALTY_YEARS_THRESHOLD = 2;
32	const LOYALTY_DISCOUNT_RATE = 0.2;
33	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
34	
35	const BASE_PREMIUMS: Record<string, number> = {
36	  sword: 100,
37	  amulet: 60,
38	  staff: 80,
39	  potion: 40,
40	  rune: 25,
41	  moonstone: 25,
42	};
43	
44	const INSURANCE_VALUES: Record<string, number> = {
45	  sword: 1000,
46	  amulet: 600,
47	  staff: 800,
48	  potion: 400,
49	  rune: 250,
50	  moonstone: 250,
51	};
52	
53	const DEDUCTIBLE_PER_DAMAGE = 100;
54	const CAP_MULTIPLE = 2;
55	
56	const BLOCK_SIZE = 3;
57	const BLOCK_PREMIUM = 60;
58	
59	/** Items that share the same `type`, and so are priced together. */
60	type AlikeItems = Item[];
61	
62	const groupAlikeItems = (items: Item[]): AlikeItems[] => {
63	  const byType = new Map<string, AlikeItems>();
64	  items.forEach((item) => byType.set(item.type, [...(byType.get(item.type) ?? []), item]));
65	  return [...byType.values()];
66	};
67	
68	const formsBlock = (items: AlikeItems): boolean => items.length === BLOCK_SIZE;
69	
70	const itemBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
71	
72	const alikeItemsBasePremium = (alikeItems: AlikeItems): number =>
73	  formsBlock(alikeItems)
74	    ? BLOCK_PREMIUM
75	    : alikeItems.reduce((total, item) => total + itemBasePremium(item), 0);
76	
77	const totalBasePremium = (items: Item[]): number =>
78	  groupAlikeItems(items).reduce((total, alikeItems) => total + alikeItemsBasePremium(alikeItems), 0);
79	
80	const isCursed = (item: Item): boolean => item.cursed === true;
81	
82	const isHighlyEnchanted = (item: Item): boolean =>
83	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
84	
85	/**
86	 * An additive rate rule: contributes `rate` × some base premium, but only to
87	 * subjects the rule `applies` to. Every rule is an independent additive term —
88	 * nothing compounds onto a running total — so a discount is simply a negative
89	 * `rate` rather than a subtraction applied at some point in a sequence.
90	 */
91	type RateRule<Subject> = { applies: (subject: Subject) => boolean; rate: number };
92	
93	/**
94	 * The combined rate of every rule that applies to `subject`. Callers multiply
95	 * this by the relevant base premium once, which keeps each rule additive.
96	 */
97	const combinedRate = <Subject>(rules: RateRule<Subject>[], subject: Subject): number =>
98	  rules.filter(({ applies }) => applies(subject)).reduce((total, { rate }) => total + rate, 0);
99	
100	/** Charged on each cursed/enchanted item's own base premium, not the policy's. */
101	const ITEM_SURCHARGES: RateRule<Item>[] = [
102	  { applies: isCursed, rate: CURSE_SURCHARGE_RATE },
103	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
104	];
105	
106	const itemSurcharge = (item: Item): number =>
107	  itemBasePremium(item) * combinedRate(ITEM_SURCHARGES, item);
108	
109	const policySurcharges = (items: Item[]): number =>
110	  items.reduce((total, item) => total + itemSurcharge(item), 0);
111	
112	/** Everything a policy-wide rule may look at when deciding whether it applies. */
113	type Policy = { customer: Customer; priorContracts: number };
114	
115	const isLoyalCustomer = ({ customer }: Policy): boolean =>
116	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
117	
118	const isFollowUpContract = ({ priorContracts }: Policy): boolean => priorContracts > 0;
119	
120	/**
121	 * Charged once per quote on the policy's base premium.
122	 *
123	 * The unconditional first-insurance surcharge is deliberately not in this table:
124	 * see `FIRST_INSURANCE_SURCHARGE_RATE` at the quote site.
125	 */
126	const POLICY_ADJUSTMENTS: RateRule<Policy>[] = [
127	  { applies: isLoyalCustomer, rate: -LOYALTY_DISCOUNT_RATE },
128	  { applies: isFollowUpContract, rate: -FOLLOW_UP_DISCOUNT_RATE },
129	];
130	
131	const policyAdjustments = (policyBasePremium: number, policy: Policy): number =>
132	  policyBasePremium * combinedRate(POLICY_ADJUSTMENTS, policy);
133	
134	const quotePremium = (items: Item[], policy: Policy): number => {
135	  const policyBasePremium = totalBasePremium(items);
136	  // The first-insurance surcharge has no condition to test: the MHPCO treats
137	  // every item in a quote as newly insured, so it is charged on every quote,
138	  // including a long-standing customer's follow-up contract. That makes it a
139	  // fixed rate on the base — like PROCESSING_FEE is a fixed addend — rather
140	  // than a rule belonging in POLICY_ADJUSTMENTS.
141	  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
142	  // Every term is added to the base, never multiplied onto a running total. The
143	  // algebraically equivalent base * (1 + rate) yields 110.00000000000001 for
144	  // base 100, which Math.ceil turns into a premium that is 1 G too high.
145	  return Math.ceil(
146	    policyBasePremium +
147	      policySurcharges(items) +
148	      firstInsuranceSurcharge +
149	      policyAdjustments(policyBasePremium, policy) +
150	      PROCESSING_FEE,
151	  );
152	};
153	
154	const isQuote = (step: Step): boolean => step.op === "quote";
155	
156	/**
157	 * A contract is created by each quote, so the number the customer already held
158	 * when `stepIndex` is reached is just the number of quotes before it. Claims are
159	 * not contracts and so do not count.
160	 */
161	const priorContractsAt = (steps: Step[], stepIndex: number): number =>
162	  steps.slice(0, stepIndex).filter(isQuote).length;
163	
164	const insuredItems = (steps: Step[], policyIndex: number): Item[] => {
165	  const step = steps[policyIndex];
166	  if (step?.op !== "quote") throw new Error(`Step ${policyIndex} did not create a policy`);
167	  return step.items;
168	};
169	
170	const insuranceSum = (items: Item[]): number =>
171	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
172	
173	const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE_PER_DAMAGE;
174	
175	const claimResult = (steps: Step[], policyIndex: number, damages: Damage[]) => {
176	  const payout = Math.floor(damages.reduce((total, damage) => total + damagePayout(damage), 0));
177	  const cap = insuranceSum(insuredItems(steps, policyIndex)) * CAP_MULTIPLE;
178	  return { payout, remainingCap: cap - payout };
179	};
180	
181	export const runScenario = (scenario: Scenario): Result[] =>
182	  scenario.steps.map((step, stepIndex) => {
183	    if (step.op === "quote") {
184	      const policy = {
185	        customer: scenario.customer,
186	        priorContracts: priorContractsAt(scenario.steps, stepIndex),
187	      };
188	      return { premium: quotePremium(step.items, policy) };
189	    }
190	    return claimResult(scenario.steps, step.policy, step.incident.damages);
191	  });
