/** The deductible is charged per damaged item, not once per incident. */
const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE_PER_DAMAGE;

const incidentPayout = (damages: Damage[]): number =>
  // Rounded down, in the MHPCO's favor. Applied to the incident total rather
  // than to each damage, so a single incident loses at most 1 G to rounding.
  Math.floor(damages.reduce((total, damage) => total + damagePayout(damage), 0));

/** A policy pays out at most twice the insurance sum of the items it covers. */
const payoutCap = (items: Item[]): number =>
  insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;

const claimResult = (steps: Step[], policyIndex: number, damages: Damage[]) => {
  const payout = incidentPayout(damages);
  return { payout, remainingCap: payoutCap(insuredItems(steps, policyIndex)) - payout };
};
